class TFMPageAdhocMenuItemsAdditionalProperties extends TFMPageMenuItemsAdditionalProperties
{

    TFMDocumentTypeId           documentType;
    TFMDocumentContentSubject   contentType;
    boolean						refreshOnSuccess;
    TFMPageID                   pageId;

}

Method.Source:
public boolean parmRefreshOnSuccess(boolean	_refreshOnSuccess = refreshOnSuccess)
{
    refreshOnSuccess = _refreshOnSuccess;
    return refreshOnSuccess;
}

public TFMDocumentContentSubject parmContentType(TFMDocumentContentSubject _contentType = contentType)
{
    contentType = _contentType;

    return contentType;
}

public TFMDocumentTypeId parmDocumentType(TFMDocumentTypeId _documentType = documentType)
{
    documentType = _documentType;

    return documentType;
}

public TFMPageID parmNavigateTo(TFMPageID _pageId = pageId)
{
    pageId = _pageId;

    return pageId;
}

public Map getparameters()
{
    Map ret = super();
    ret.insert('/onSuccessfulPost/navigateTo',[pageId]);
    ret.insert('/onSuccessfulPost/refreshOnSuccess',[refreshOnSuccess]);
    ret.insert('/documentName', [documentType]);
    ret.insert('/registrationType', [contentType]);
    return ret;
}
